foreach ($screen in $screens) {
    Write-Host "Downloading $($screen.name)..."
    $imgPath = Join-Path $outDir "$($screen.name).png"
    $htmlPath = Join-Path $outDir "$($screen.name).html"
    
    # Use curl.exe as it handles these URLs gracefully (sometimes PowerShell's native webcmdlets have issues with strict headers)
    curl.exe -L -s -o $imgPath $screen.imgUrl
    curl.exe -L -s -o $htmlPath $screen.htmlUrl
}
Write-Host "Done downloading all screens."
